     LEGACY_R93_EARTH_SYSTEM_ENGINE_SCHEMA,
    LEGACY_R92_EARTH_SYSTEM_ENGINE_SCHEMA,
    LEGACY_R91_EARTH_SYSTEM_ENGINE_SCHEMA,
      LEGACY_R90_EARTH_SYSTEM_ENGINE_SCHEMA,
      LEGACY_R89_EARTH_SYSTEM_ENGINE_SCHEMA,
     LEGACY_R88_EARTH_SYSTEM_ENGINE_SCHEMA,
      LEGACY_R87_EARTH_SYSTEM_ENGINE_SCHEMA,
      LEGACY_R86_EARTH_SYSTEM_ENGINE_SCHEMA,
      LEGACY_R85_EARTH_SYSTEM_ENGINE_SCHEMA,
      LEGACY_R84_EARTH_SYSTEM_ENGINE_SCHEMA,
      LEGACY_R83_EARTH_SYSTEM_ENGINE_SCHEMA,
      LEGACY_R82_EARTH_SYSTEM_ENGINE_SCHEMA,
      LEGACY_R81_EARTH_SYSTEM_ENGINE_SCHEMA,
      LEGACY_R80_EARTH_SYSTEM_ENGINE_SCHEMA,
      LEGACY_R79_EARTH_SYSTEM_ENGINE_SCHEMA,
      'axm.foundation-planet.earth-system-engine/v39',
      'axm.foundation-planet.earth-system-engine/v38',
      'axm.foundation-planet.earth-system-engine/v37',
